mapper.select:
SELECT d.id, d.dir_id, d.title, d.content, d.owner_id, u.username as owner_name,
       d.visibility, d.status, d.current_version, d.sort, d.published_at, d.created_at, d.updated_at
FROM documents d LEFT JOIN users u ON u.id = d.owner_id

