mapper.select:
SELECT v.id, v.doc_id, v.version_no, v.title, v.content, v.owner_id, u.username as owner_name, v.note, v.created_at
FROM doc_versions v LEFT JOIN users u ON u.id = v.owner_id
WHERE v.doc_id = #{docId} AND v.version_no = #{versionNo}
